import React, { useState, useEffect } from 'react';
import axios from 'axios';

// Create the App component here
const App = () => {
  // Initialize token state here
  const [tokens, setTokens] = useState({ accessToken: '', refreshToken: '' });

  // Create axios instance with base configuration
  const axiosInstance = axios.create({
    baseURL: 'https://api.example.com'
  });

  // Add request interceptor here
  axiosInstance.interceptors.request.use(
    (config) => {
      if (tokens.accessToken) {
        config.headers.Authorization = `Bearer ${tokens.accessToken}`;
      }
      return config;
    },
    (error) => Promise.reject(error)
  );

  // Add response interceptor here
  axiosInstance.interceptors.response.use(
    (response) => response,
    async (error) => {
      const originalRequest = error.config;
      if (error.response?.status === 401 && !originalRequest._retry) {
        originalRequest._retry = true;
        try {
          const newAccessToken = await refreshToken();
          setTokens(prev => ({ ...prev, accessToken: newAccessToken }));
          originalRequest.headers.Authorization = `Bearer ${newAccessToken}`;
          return axiosInstance(originalRequest);
        } catch (refreshError) {
          return Promise.reject(refreshError);
        }
      }
      return Promise.reject(error);
    }
  );

  // Create token refresh function here
  const refreshToken = async () => {
    // Simulate token refresh
    const newToken = `refreshed_${Date.now()}`;
    setTokens(prev => ({ ...prev, accessToken: newToken }));
    return newToken;
  };

  // Create login simulation function here
  const login = async () => {
    // Simulate login
    const mockTokens = {
      accessToken: `access_${Date.now()}`,
      refreshToken: `refresh_${Date.now()}`
    };
    setTokens(mockTokens);
  };

  return (
    <div>
      <h1>Token Refresh Demo</h1>
      <button>Login</button>
      <button>Refresh Token</button>
    </div>
  );
};
